def priority(item: float, bins: np.ndarray) -> np.ndarray:
    rem = bins - item
    scores = np.where(rem >= 0, -rem, -np.inf)
    empty_mask = (bins == np.max(bins)) & (rem >= 0)
    if not np.any(scores != -np.inf):
        return np.zeros_like(bins)
    max_cap = np.max(bins)
    scores = np.where(bins == max_cap, np.maximum(scores, -max_cap * 0.5), scores)
    return scores
